INSERT INTO goods (id, seller_id, school_id, campus_id, category_id, title, description, cover_url, price, original_price, condition_level, trade_mode, location, stock, status, published_at) VALUES
  (90001, 9001, 1, 1, 101, '高等数学 同济第七版 上下册', '上册有少量铅笔笔记，下册几乎全新，期末复习够用。', 'http://localhost:8080/uploads/demo/goods-90001.svg', 25.00, 68.00, 3, 3, '图书馆门口', 1, 2, NOW() - INTERVAL 7 HOUR),
  (90002, 9003, 1, 1, 101, '大学物理学 第四版 上册', '物理课指定教材，书角有磨损，无缺页。', 'http://localhost:8080/uploads/demo/goods-90002.svg', 18.00, 45.00, 4, 1, '一食堂门口', 1, 2, NOW() - INTERVAL 14 HOUR),
  (90003, 9002, 1, 2, 101, '数据结构 C语言版 严蔚敏', '计算机专业课教材，重点章节有荧光笔标注。', 'http://localhost:8080/uploads/demo/goods-90003.svg', 20.00, 35.00, 3, 3, '廷根三教', 1, 2, NOW() - INTERVAL 21 HOUR),
  (90004, 9002, 1, 2, 101, '线性代数 同济第六版', '几乎全新，只翻过前两章。', 'http://localhost:8080/uploads/demo/goods-90004.svg', 12.00, 26.00, 2, 1, '廷根三教', 0, 5, NOW() - INTERVAL 28 HOUR),
  (90005, 9001, 1, 1, 102, '2026 考研英语真题 黄皮书', '2010-2025 真题带详解，做过前五年，答案写在草稿纸上，书面干净。', 'http://localhost:8080/uploads/demo/goods-90005.svg', 30.00, 79.00, 2, 3, '图书馆门口', 1, 2, NOW() - INTERVAL 35 HOUR),
  (90006, 9002, 1, 2, 102, '计算机二级 MS Office 题库', '附赠刷题软件激活码（已过期），书本身可用。', 'http://localhost:8080/uploads/demo/goods-90006.svg', 10.00, 39.00, 3, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 42 HOUR),
  (90007, 9003, 1, 1, 103, '三体 全三册 典藏版', '看过一遍，保存很好，无折痕。', 'http://localhost:8080/uploads/demo/goods-90007.svg', 35.00, 93.00, 2, 3, '南区 5 栋', 1, 2, NOW() - INTERVAL 49 HOUR),
  (90008, 9002, 1, 2, 103, '活着 余华', '经典小说，书页略发黄。', 'http://localhost:8080/uploads/demo/goods-90008.svg', 8.00, 20.00, 3, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 56 HOUR),
  (90009, 9001, 1, 1, 201, 'iPad Air 5 64G 蓝色', '国行，电池健康 92%，带原装充电器和保护壳，屏幕无划痕。', 'http://localhost:8080/uploads/demo/goods-90009.svg', 2300.00, 4399.00, 2, 2, '图书馆门口', 1, 2, NOW() - INTERVAL 63 HOUR),
  (90010, 9002, 1, 2, 201, '红米 Note 12 备用机 8+128', '换新机出，边框有小磕碰，功能全好。', 'http://localhost:8080/uploads/demo/goods-90010.svg', 450.00, 1199.00, 3, 3, '廷根三教', 1, 2, NOW() - INTERVAL 70 HOUR),
  (90011, 9003, 1, 1, 201, 'Kindle Paperwhite 5 8G', '宿舍看书神器，带皮套，屏幕完好。', 'http://localhost:8080/uploads/demo/goods-90011.svg', 380.00, 1068.00, 2, 3, '南区 5 栋', 1, 2, NOW() - INTERVAL 77 HOUR),
  (90012, 9001, 1, 1, 202, '戴尔 24 寸 IPS 显示器 P2422H', '毕业清仓，无坏点，带 DP 线和电源线，宿舍桌面刚好放下。', 'http://localhost:8080/uploads/demo/goods-90012.svg', 450.00, 1299.00, 2, 1, '北区 2 栋楼下', 1, 2, NOW() - INTERVAL 84 HOUR),
  (90013, 9003, 1, 1, 202, '联想 19 寸旧显示器', '老款 1440x900，能正常显示，适合当副屏，有轻微漏光。', 'http://localhost:8080/uploads/demo/goods-90013.svg', 80.00, 599.00, 4, 1, '南区 5 栋', 1, 2, NOW() - INTERVAL 91 HOUR),
  (90014, 9002, 1, 2, 202, 'AOC 27 寸 2K 显示器 Q27G2', '165Hz 电竞屏，打游戏写代码都好用，原包装还在。', 'http://localhost:8080/uploads/demo/goods-90014.svg', 680.00, 1399.00, 2, 3, '廷根宿舍区', 1, 2, NOW() - INTERVAL 98 HOUR),
  (90015, 9002, 1, 2, 202, '小米 23.8 寸显示器 1A', '1080P，带底座，宿舍用了一年，屏幕干净。', 'http://localhost:8080/uploads/demo/goods-90015.svg', 260.00, 599.00, 3, 3, '廷根三教', 1, 2, NOW() - INTERVAL 105 HOUR),
  (90016, 9001, 1, 1, 202, '罗技 K380 蓝牙键盘', '可连三台设备，键帽无打油，送两节电池。', 'http://localhost:8080/uploads/demo/goods-90016.svg', 90.00, 199.00, 2, 3, '图书馆门口', 1, 2, NOW() - INTERVAL 112 HOUR),
  (90017, 9002, 1, 2, 202, '罗技 G102 有线鼠标', 'RGB 灯效正常，微动无连击。', 'http://localhost:8080/uploads/demo/goods-90017.svg', 45.00, 129.00, 3, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 119 HOUR),
  (90018, 9003, 1, 1, 202, '笔记本散热支架 铝合金', '可调高度，折叠后能放进书包。', 'http://localhost:8080/uploads/demo/goods-90018.svg', 25.00, 69.00, 2, 1, '一食堂门口', 1, 2, NOW() - INTERVAL 126 HOUR),
  (90019, 9002, 1, 2, 203, 'AirPods 第三代', '左右耳和充电盒都正常，已消毒，序列号可查。', 'http://localhost:8080/uploads/demo/goods-90019.svg', 520.00, 1399.00, 2, 2, '廷根三教', 1, 2, NOW() - INTERVAL 133 HOUR),
  (90020, 9003, 1, 1, 203, '漫步者 W820NB 降噪耳机', '头戴式，降噪效果不错，耳罩有轻微脱皮。', 'http://localhost:8080/uploads/demo/goods-90020.svg', 150.00, 399.00, 3, 3, '南区 5 栋', 1, 2, NOW() - INTERVAL 140 HOUR),
  (90021, 9001, 1, 1, 203, '小米蓝牙音箱 随身版', '音质够宿舍用，续航 6 小时左右。', 'http://localhost:8080/uploads/demo/goods-90021.svg', 40.00, 99.00, 3, 1, '北区 2 栋楼下', 1, 2, NOW() - INTERVAL 147 HOUR),
  (90022, 9003, 1, 1, 301, '小熊电煮锅 1.2L', '宿舍煮面神器，不粘涂层完好，功率 600W 不跳闸。', 'http://localhost:8080/uploads/demo/goods-90022.svg', 35.00, 89.00, 3, 1, '南区 5 栋', 1, 2, NOW() - INTERVAL 154 HOUR),
  (90023, 9001, 1, 1, 301, '护眼 LED 台灯 三档调光', 'USB 充电，晚上看书不刺眼，夹子式可夹床边。', 'http://localhost:8080/uploads/demo/goods-90023.svg', 20.00, 59.00, 2, 1, '北区 2 栋楼下', 1, 2, NOW() - INTERVAL 161 HOUR),
  (90024, 9002, 1, 2, 301, '美的 USB 小风扇 静音', '放床头吹很安静，三档风速。', 'http://localhost:8080/uploads/demo/goods-90024.svg', 25.00, 59.00, 3, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 168 HOUR),
  (90025, 9002, 1, 2, 301, '小米电热水壶 1.5L', '烧水快，水垢已清理。', 'http://localhost:8080/uploads/demo/goods-90025.svg', 30.00, 79.00, 3, 3, '廷根宿舍区', 1, 2, NOW() - INTERVAL 175 HOUR),
  (90026, 9003, 1, 1, 301, '公牛 6 位插排 带 USB', '1.8 米线，宿舍桌面够用。', 'http://localhost:8080/uploads/demo/goods-90026.svg', 15.00, 49.00, 2, 1, '一食堂门口', 1, 2, NOW() - INTERVAL 182 HOUR),
  (90027, 9001, 1, 1, 301, '小米台灯 1S', '支持米家 App 调光，已下架自用。', 'http://localhost:8080/uploads/demo/goods-90027.svg', 60.00, 169.00, 2, 1, '北区 2 栋楼下', 1, 6, NOW() - INTERVAL 189 HOUR),
  (90028, 9003, 1, 1, 302, '宿舍遮光床帘 上铺', '加厚遮光布，含支架，拆装方便。', 'http://localhost:8080/uploads/demo/goods-90028.svg', 40.00, 129.00, 2, 1, '南区 5 栋', 1, 2, NOW() - INTERVAL 196 HOUR),
  (90029, 9002, 1, 2, 302, '收纳箱 三个一起', '大号带轮子，毕业搬家清理出来的。', 'http://localhost:8080/uploads/demo/goods-90029.svg', 20.00, 75.00, 3, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 203 HOUR),
  (90030, 9002, 1, 2, 302, '全新衣架 20 个', '买多了，免费送，自取。', 'http://localhost:8080/uploads/demo/goods-90030.svg', 0.00, NULL, 1, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 210 HOUR),
  (90031, 9001, 1, 1, 401, '优衣库 轻型羽绒服 L 码 黑色', '穿过一个冬天，已干洗。', 'http://localhost:8080/uploads/demo/goods-90031.svg', 120.00, 499.00, 3, 3, '图书馆门口', 1, 2, NOW() - INTERVAL 217 HOUR),
  (90032, 9002, 1, 2, 401, '本科学士服 一套', '毕业照穿过一次，含帽子和垂布。', 'http://localhost:8080/uploads/demo/goods-90032.svg', 30.00, 120.00, 2, 1, '廷根三教', 1, 2, NOW() - INTERVAL 224 HOUR),
  (90033, 9003, 1, 1, 402, '耐克 Air Force 1 42 码', '白色，鞋面有折痕，已清洗。', 'http://localhost:8080/uploads/demo/goods-90033.svg', 260.00, 799.00, 3, 3, '南区 5 栋', 1, 2, NOW() - INTERVAL 231 HOUR),
  (90034, 9002, 1, 2, 402, '小米 双肩包 商务款', '能放 15.6 寸笔记本，拉链顺滑。', 'http://localhost:8080/uploads/demo/goods-90034.svg', 40.00, 149.00, 3, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 238 HOUR),
  (90035, 9001, 1, 1, 501, '捷安特 ATX 山地车', '27 速，刹车和变速都调过，送车锁。', 'http://localhost:8080/uploads/demo/goods-90035.svg', 600.00, 1998.00, 3, 1, '北区车棚', 1, 2, NOW() - INTERVAL 245 HOUR),
  (90036, 9002, 1, 2, 501, '雅迪 二手电动车 带充电器', '续航 30 公里左右，电池去年换过。', 'http://localhost:8080/uploads/demo/goods-90036.svg', 1200.00, 2999.00, 4, 1, '廷根车棚', 1, 2, NOW() - INTERVAL 252 HOUR),
  (90037, 9003, 1, 1, 502, '尤尼克斯 羽毛球拍 弓箭 11', '已穿线 24 磅，拍框无裂痕。', 'http://localhost:8080/uploads/demo/goods-90037.svg', 150.00, 599.00, 2, 3, '体育馆门口', 1, 2, NOW() - INTERVAL 259 HOUR),
  (90038, 9002, 1, 2, 502, '加厚瑜伽垫 10mm', '宿舍做拉伸用，带收纳绑带。', 'http://localhost:8080/uploads/demo/goods-90038.svg', 25.00, 79.00, 2, 1, '廷根宿舍区', 1, 2, NOW() - INTERVAL 266 HOUR),
  (90039, 9001, 1, 1, 502, '可调哑铃 10kg 一对', '包胶哑铃，不伤地板。', 'http://localhost:8080/uploads/demo/goods-90039.svg', 60.00, 159.00, 3, 1, '北区 2 栋楼下', 1, 2, NOW() - INTERVAL 273 HOUR),
  (90040, 9002, 1, 2, 601, '雅马哈 F310 民谣吉他', '送琴包、变调夹和备用弦，琴颈笔直。', 'http://localhost:8080/uploads/demo/goods-90040.svg', 500.00, 1080.00, 3, 3, '廷根宿舍区', 1, 2, NOW() - INTERVAL 280 HOUR);
